window.RP_SESSION={"id":"S-c67c47f73ea1","messages":[{"id":"RP-III-0155975","time":"2026-08-23T06:53:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 눈... 그 눈... 그 검은 두 눈... \"\n\n머챈트 마이어.\n\n그녀는 며칠 전, 하마이잔 마을 안에서 정체모를 괴물과의 전투 이후 큰 충격에 빠진다.\n\n머리속에 떠오른 선명한 검은 여인의 형상.\n\n그것은 단순한 이미지가 아닌 죽음의 기억이었다.\n\n그녀는 자신이 어떻게 동굴 밖으로 빠져나왔는지 기억하지 못했다.\n\n아서의 도움이었을까? 아니면 아이다?","characters":["P-92738ae601c0"]},{"id":"RP-III-0155976","time":"2026-08-23T06:55:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 눈... 그 눈... 그 검은 두 눈... \"\n\n어떻게 검은 여인의 이미지가 머리속에 떠오른 걸까? 난 그런 기억을 가진 적이 없는데.\n\n내 머리속에 들어오기라도 한 걸까?\n\n검은 여인이?\n아니면 죽음이?","characters":["P-92738ae601c0"]},{"id":"RP-III-0155977","time":"2026-08-23T07:00:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"으...\"\n\n여관 방에 누워서, 붕대를 감고 골골거리는 위크. 신체적, 정신적으로 피폐해진 탓에 반쯤은 폐인이 된 모습이다...","characters":["P-d129df648db5"]},{"id":"RP-III-0155978","time":"2026-08-23T07:03:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"그도 순간 머릿속에 들어온 여인의 이미지와 두 눈을 기억합니다. 오히려 잊을 수가 없다고 말하는 게 정확하겠군요.","characters":["P-d129df648db5"]},{"id":"RP-III-0155979","time":"2026-08-23T07:04:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 ...  \"\n\n머챈트는 침대 위에 웅크려 앉아 같은 말을 되풀이하며 떨고 있을 뿐입니다.","characters":["P-92738ae601c0"]},{"id":"RP-III-0155980","time":"2026-08-23T07:11:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"조용히 좀 하라고 한 마디 하려다 참습니다. 자신도 그 이미지가 얼마나 무섭고, 마음속 깊숙히 파고들었는지 알았기에...","characters":["P-d129df648db5"]},{"id":"RP-III-0155981","time":"2026-08-23T07:14:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 ...  \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0155982","time":"2026-08-23T07:24:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 두 눈... \"\n\" 눈... 그 눈... 그 검은 ...  \"","characters":["P-92738ae601c0"]},{"id":"RP-III-0155983","time":"2026-08-23T07:26:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"...\"","characters":["P-d129df648db5"]},{"id":"RP-III-0155984","time":"2026-08-23T07:34:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"리듬이 느껴집니다. 악기를 집...\n\n없네요.","characters":["P-d129df648db5"]},{"id":"RP-III-0155985","time":"2026-08-23T07:35:00+09:00","room":"RP III","name":"위크 골든리프","profile":"햄 찌","identity":"reviewed","type":"dialogue","body":"\"조용히.... 커억!!\"\n\n소리지르다 말고 가슴을 부여잡고 드러눕습니다. 애처롭네요.","characters":["P-d129df648db5"]},{"id":"RP-III-0155986","time":"2026-08-23T07:52:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"고통과 공포의 밤은 계속 이어졌습니다.","characters":["P-92738ae601c0"]},{"id":"RP-III-0155987","time":"2026-08-23T07:52:00+09:00","room":"RP III","name":"머챈트 마이어","profile":"카리엔","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-92738ae601c0"]},{"id":"RP-III-0155988","time":"2026-08-23T07:52:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...다음 시간에.","characters":[]}]};
